        assert_eq!(router.counters(), RouterCounters { failures: 1, no_progress: 2 });
        assert_eq!(router.record(StepOutcome::Progress), Tier::Fast);
        assert_eq!(router.counters(), RouterCounters { failures: 0, no_progress: 0 });
    }
}

