    fn repairs_extra_fields_and_option() {
        let payload = "{\"type\":\"select\",\"id\":\"el_2\",\"option\":\"blue\",\"reason\":\"\"}";
        let action = repair_action(payload, &schema()).expect("repair action");
        assert_eq!(
