                scroll: None,
                wait_ms: None,
                query_len: None,
                summary_len: None,
            },
            Action::Back => ActionSummary {
                action_type: "back",
                id: None,
                text_len: None,
                submit: None,
                value_len: None,
                url: None,
                scroll: None,
                wait_ms: None,
                query_len: None,
                summary_len: None,
            },
            Action::Extract { query, id } => ActionSummary {
                action_type: "extract",
                id: id.as_deref(),
                text_len: None,
                submit: None,
                value_len: None,
                url: None,
                scroll: None,
                wait_ms: None,
                query_len: Some(query.chars().count()),
                summary_len: None,
            },
            Action::Done { summary } => ActionSummary {
                action_type: "done",
                id: None,
                text_len: None,
                submit: None,
                value_len: None,
                url: None,
                scroll: None,
                wait_ms: None,
                query_len: None,
                summary_len: Some(summary.chars().count()),
