#[derive(Debug)]
struct Timeouts {
    snapshot: Duration,
    action: Duration,
}

#[derive(Debug)]
struct CdpSession {
    browser: Mutex<ChromiumBrowser>,
    page: Mutex<Page>,
    handler_task: Mutex<Option<tokio::task::JoinHandle<()>>>,
    owns_browser: bool,
    closed: AtomicBool,
}

impl CdpSession {
    async fn launch(config: &CdpConfig) -> BrowserResult<Self> {
        let mut builder = BrowserConfig::builder();
        if config.headful {
            builder = builder.with_head();
        }
        let browser_config = builder
            .build()
            .map_err(|err| BrowserError::new("config_error", err))?;
        let (browser, mut handler) = ChromiumBrowser::launch(browser_config)
            .await
            .map_err(|err| BrowserError::new("cdp_launch_failed", err.to_string()))?;
        let handler_task = tokio::spawn(async move {
            while let Some(_event) = handler.next().await {}
        });
        let page = create_page(&browser, &config.initial_url).await?;

        Ok(Self {
            browser: Mutex::new(browser),
            page: Mutex::new(page),
            handler_task: Mutex::new(Some(handler_task)),
            owns_browser: true,
            closed: AtomicBool::new(false),
        })
    }

    async fn connect(config: &CdpConfig, url: &str) -> BrowserResult<Self> {
        let (browser, mut handler) = ChromiumBrowser::connect(url)
            .await
            .map_err(|err| BrowserError::new("cdp_connect_failed", err.to_string()))?;
        let handler_task = tokio::spawn(async move {
            while let Some(_event) = handler.next().await {}
        });
        let page = create_page(&browser, &config.initial_url).await?;

        Ok(Self {
            browser: Mutex::new(browser),
            page: Mutex::new(page),
            handler_task: Mutex::new(Some(handler_task)),
            owns_browser: false,
            closed: AtomicBool::new(false),
        })
    }

    async fn shutdown(&self) -> BrowserResult<()> {
        if self.closed.swap(true, Ordering::SeqCst) {
            return Ok(());
        }

        let page = self.page.lock().await.clone();
        page.close()
            .await
            .map_err(|err| BrowserError::new("cdp_page_close_failed", err.to_string()))?;

        if self.owns_browser {
            let mut browser = self.browser.lock().await;
            browser
                .close()
                .await
                .map_err(|err| BrowserError::new("cdp_close_failed", err.to_string()))?;
        }

        let mut handler_opt = self.handler_task.lock().await;
        if let Some(mut handle) = handler_opt.take() {
            let shutdown_timer = tokio::time::sleep(Duration::from_secs(5));
            tokio::pin!(shutdown_timer);
            tokio::select! {
                result = &mut handle => {
                    if let Err(err) = result {
                        return Err(BrowserError::new("cdp_handler_failed", err.to_string()));
                    }
                }
                _ = &mut shutdown_timer => {
                    handle.abort();
                    let _ = handle.await;
                }
            }
        }

        Ok(())
    }

    async fn page(&self) -> Page {
        self.page.lock().await.clone()
    }
}

async fn create_page(browser: &ChromiumBrowser, initial_url: &str) -> BrowserResult<Page> {
    let page = browser
        .new_page("about:blank")
        .await
        .map_err(|err| BrowserError::new("cdp_page_failed", err.to_string()))?;
    if !initial_url.is_empty() && initial_url != "about:blank" {
        page.goto(initial_url)
            .await
            .map_err(|err| BrowserError::new("cdp_nav_failed", err.to_string()))?;
    }
    Ok(page)
}

#[derive(Debug)]
pub struct CdpBrowser {
    session: CdpSession,
    observer: Observer,
    applier: ActionApplier,
    timeouts: Timeouts,
    element_map: Mutex<HashMap<String, BackendNodeId>>,
}

impl CdpBrowser {
    pub async fn bootstrap(config: CdpConfig) -> BrowserResult<()> {
        let browser = Self::start(config).await?;
        browser.shutdown().await?;
        Ok(())
    }

    pub async fn launch(config: CdpConfig) -> BrowserResult<Self> {
        let session = CdpSession::launch(&config).await?;
        Ok(Self::from_session(session, &config))
    }

    pub async fn start(config: CdpConfig) -> BrowserResult<Self> {
        if let Some(url) = config.cdp_url.as_deref().filter(|value| !value.is_empty()) {
            let session = CdpSession::connect(&config, url).await?;
            Ok(Self::from_session(session, &config))
        } else {
            Self::launch(config).await
        }
    }

    fn from_session(session: CdpSession, config: &CdpConfig) -> Self {
        let observer = Observer::new(ObserverConfig {
            max_elements: config.max_elements,
            max_text_len: config.max_text_len,
        });
        Self {
            session,
            observer,
            applier: ActionApplier::new(config.max_scroll, config.max_wait_ms),
            timeouts: Timeouts {
                snapshot: config.snapshot_timeout,
                action: config.action_timeout,
            },
            element_map: Mutex::new(HashMap::new()),
        }
    }
}

#[async_trait]
impl Browser for CdpBrowser {
    async fn snapshot(&self) -> BrowserResult<Observation> {
        let snapshot = {
            let page = self.session.page().await;
            let result = timeout(self.timeouts.snapshot, self.observer.snapshot(&page)).await;
            match result {
                Ok(snapshot) => snapshot?,
                Err(err) => {
                    return Err(BrowserError::new(
                        "timeout",
                        format!("snapshot timed out: {err}"),
                    ))
                }
            }
        };

        let mut map = self.element_map.lock().await;
        *map = snapshot.element_map;
        Ok(snapshot.observation)
    }

    async fn apply(&self, action: &Action) -> BrowserResult<StepResult> {
        let page = self.session.page().await;
        let map = { self.element_map.lock().await.clone() };
        let timeout_duration = match action {
            Action::Wait { ms } => {
                let wait = Duration::from_millis(*ms);
                let padded = wait
                    .checked_add(Duration::from_millis(50))
                    .unwrap_or(wait);
                if padded > self.timeouts.action {
                    padded
                } else {
                    self.timeouts.action
                }
            }
            _ => self.timeouts.action,
        };
        let result = timeout(
            timeout_duration,
            self.applier.apply(&page, action, Some(&map)),
        )
        .await;
        let step = match result {
            Ok(Ok(outcome)) => action_result_ok_with(outcome),
            Ok(Err(err)) => action_result_err(err),
            Err(err) => action_result_err(ActionError::new(
                "timeout",
                format!("action timed out: {err}"),
            )),
        };
        Ok(step)
    }

    async fn shutdown(&self) -> BrowserResult<()> {
        self.session.shutdown().await
    }
}

impl From<chromiumoxide::error::CdpError> for BrowserError {
    fn from(err: chromiumoxide::error::CdpError) -> Self {
        BrowserError::new("cdp_error", err.to_string())
    }
}

impl Drop for CdpBrowser {
    fn drop(&mut self) {
        if !self.session.closed.load(Ordering::SeqCst) {
            if let Ok(mut handler_opt) = self.session.handler_task.try_lock() {
                if let Some(handle) = handler_opt.take() {
                    handle.abort();
                }
            }
        }
    }
}

use crate::limits::exceeds_symmetric_limit_i64;
use crate::types::{Action, Observation};
use reqwest::Url;
use std::collections::HashSet;
use std::time::Duration;

#[derive(Clone, Debug)]
pub struct Validator {
    config: ValidatorConfig,
}

#[derive(Clone, Debug)]
pub struct ValidatorConfig {
    pub allow_insecure: bool,
    pub max_text_len: usize,
    pub max_wait_ms: u64,
    pub max_scroll: i64,
}

impl Default for ValidatorConfig {
    fn default() -> Self {
        Self {
            allow_insecure: false,
            max_text_len: 2000,
            max_wait_ms: 30_000,
            max_scroll: 2000,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ValidationError {
    pub code: String,
    pub field: Option<String>,
    pub message: String,
}

impl ValidationError {
    fn new(code: &'static str, field: Option<&'static str>, message: impl Into<String>) -> Self {
        Self {
            code: code.to_string(),
            field: field.map(|value| value.to_string()),
            message: message.into(),
        }
    }
}

impl Default for Validator {
    fn default() -> Self {
        Self::new(ValidatorConfig::default())
    }
}

impl Validator {
    pub fn new(config: ValidatorConfig) -> Self {
        Self { config }
    }

    pub fn validate(
        &self,
        action: &Action,
        observation: &Observation,
    ) -> Result<(), Vec<ValidationError>> {
        let element_ids: HashSet<&str> =
            observation.elements.iter().map(|el| el.id.as_str()).collect();
        let mut errors = Vec::new();

        match action {
            Action::Click { id } => {
                validate_element_id(id, &element_ids, &mut errors);
            }
            Action::Type { id, text, .. } => {
                validate_element_id(id, &element_ids, &mut errors);
                let length = text.chars().count();
                if length > self.config.max_text_len {
                    errors.push(ValidationError::new(
                        "text_too_long",
                        Some("text"),
                        format!(
                            "text length {} exceeds max {}",
                            length,
                            self.config.max_text_len
                        ),
                    ));
                }
            }
            Action::Select { id, .. } => {
                validate_element_id(id, &element_ids, &mut errors);
            }
            Action::Scroll { dx, dy } => {
                let limit = self.config.max_scroll;
                if exceeds_symmetric_limit_i64(*dx, limit) || exceeds_symmetric_limit_i64(*dy, limit)
                {
                    errors.push(ValidationError::new(
                        "scroll_out_of_bounds",
                        Some("scroll"),
                        format!(
                            "scroll out of bounds: dx={dx}, dy={dy}, max={limit}"
                        ),
                    ));
                }
            }
            Action::Wait { ms } => {
                if wait_exceeds_max(*ms, self.config.max_wait_ms) {
                    errors.push(ValidationError::new(
                        "wait_too_long",
                        Some("ms"),
                        format!(
                            "wait {ms}ms exceeds max {}ms",
                            self.config.max_wait_ms
                        ),
                    ));
                }
            }
            Action::Navigate { url } => {
                match parse_navigate_url(url) {
                    Ok(parsed) => {
                        if let Some(error) =
                            evaluate_url_policy(&parsed, self.config.allow_insecure)
                        {
                            errors.push(error);
                        }
                    }
                    Err(error) => errors.push(error),
                }
            }
            Action::Back => {}
            Action::Extract { id, .. } => {
                if let Some(id) = id.as_ref() {
                    validate_element_id(id, &element_ids, &mut errors);
                }
            }
            Action::Done { .. } => {}
        }

        if errors.is_empty() {
            Ok(())
        } else {
            Err(errors)
        }
    }
}

fn validate_element_id(id: &str, element_ids: &HashSet<&str>, errors: &mut Vec<ValidationError>) {
    if id.trim().is_empty() {
        errors.push(ValidationError::new(
            "missing_id",
            Some("id"),
            "action id is required",
        ));
        return;
    }

    if !element_ids.contains(id) {
        errors.push(ValidationError::new(
            "unknown_id",
            Some("id"),
            format!("id {id} not found in observation"),
        ));
    }
}

fn wait_exceeds_max(ms: u64, max_wait_ms: u64) -> bool {
    Duration::from_millis(ms) > Duration::from_millis(max_wait_ms)
}

fn parse_navigate_url(raw: &str) -> Result<Url, ValidationError> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Err(ValidationError::new(
            "missing_url",
            Some("url"),
            "navigate url is required",
        ));
    }
    Url::parse(trimmed).map_err(|err| {
        ValidationError::new(
            "invalid_url",
            Some("url"),
            format!("invalid url {trimmed}: {err}"),
        )
    })
}

fn evaluate_url_policy(url: &Url, allow_insecure: bool) -> Option<ValidationError> {
    if allow_insecure {
        return None;
    }

    match url.scheme() {
        "http" | "https" => None,
        other => Some(ValidationError::new(
            "insecure_url",
            Some("url"),
            format!("unsupported url scheme '{other}'"),
        )),
    }
}

